@register(dispatch_mode=make_nd_compute_dataproto_dispatch_fn(mesh_name="rollout"))
@DistProfiler.annotate(color="red", role="rollout_generate")
def generate_sequences(self, prompts: DataProto):
    # Support all hardwares
    assert self._is_rollout
    prompts = prompts.to(get_device_id())

    meta_info = {
        "eos_token_id": self.generation_config.eos_token_id
        if self.generation_config is not None
        else self.tokenizer.eos_token_id,
        "pad_token_id": self.generation_config.pad_token_id
        if self.generation_config is not None
        else self.tokenizer.pad_token_id,
    }
    prompts.meta_info.update(meta_info)

    timing_generate = {}
    if self._is_actor:  # For rollout only, we do not switch context.
        loop = get_event_loop()
        loop.run_until_complete(self.rollout_mode())
        log_gpu_memory_usage("After switch to rollout mode", logger=logger)

    with simple_timer("generate_sequences", timing_generate):
        output = self.rollout.generate_sequences(prompts=prompts)

    if self._is_actor:
        loop.run_until_complete(self.trainer_mode())
        log_gpu_memory_usage("After switch to trainer mode", logger=logger)

    # We calculate the average timing across all ranks
    # to make sure meta_info["timing"] is the same
    timing_generate_topk_ratio, timing_generate_min, timing_generate_max = topk_reduce_ratio_min_max(
        timing_generate["generate_sequences"]
    )
    timing_generate = reduce_timing(timing_generate)
    timing_generate.update(
        {
            "generation_timing/max": timing_generate_max,
            "generation_timing/min": timing_generate_min,
            "generation_timing/topk_ratio": timing_generate_topk_ratio,
        }
    )
    output.meta_info["timing"] = timing_generate
    output = output.to("cpu")

    # clear kv cache
    get_torch_device().empty_cache()
    return output

@register(dispatch_mode=make_nd_compute_dataproto_dispatch_fn(mesh_name="actor"))
@DistProfiler.annotate(color="blue", role="actor_compute_log_prob")
def compute_log_prob(self, data: DataProto):
    # when is_lora is True, we use the actor without lora applied to calculate the log_prob
    # which is mostly used for ref log_prob calculation
    assert self._is_actor
    if self._is_offload_param:
        load_fsdp_model_to_gpu(self.actor_module_fsdp)

    # Support all hardwares
    from contextlib import nullcontext

    is_lora = data.meta_info.pop("is_lora", False)
    adapter_ctx = self.actor.actor_module.disable_adapter() if is_lora else nullcontext()
    # we should always recompute old_log_probs when it is HybridEngine
    config_source = self.config.ref if is_lora else self.config.rollout
    data.meta_info["micro_batch_size"] = config_source.log_prob_micro_batch_size_per_gpu
    data.meta_info["max_token_len"] = config_source.log_prob_max_token_len_per_gpu
    data.meta_info["use_dynamic_bsz"] = config_source.log_prob_use_dynamic_bsz
    data.meta_info["temperature"] = self.config.rollout.temperature
    data.meta_info.setdefault("pad_token_id", self.tokenizer.pad_token_id)
    # perform recompute log_prob
    calculate_entropy = not is_lora
    with self.ulysses_sharding_manager:
        with adapter_ctx:
            outputs = self.actor.compute_log_prob(data=data, calculate_entropy=calculate_entropy)
        if not is_lora:
            tensors = {"old_log_probs": outputs["log_probs"]}
        else:
            tensors = {"ref_log_prob": outputs["log_probs"]}
        if calculate_entropy:
            tensors["entropys"] = outputs["entropys"]
        if "sum_pi_squared" in outputs:
            tensors["sum_pi_squared"] = outputs["sum_pi_squared"]
        if not is_lora and "ref_log_prob" in outputs:
            tensors["ref_log_prob"] = outputs["ref_log_prob"]
        if not is_lora and "vimpo_old_token_kl" in outputs:
            tensors["vimpo_old_token_kl"] = outputs["vimpo_old_token_kl"]
        output = DataProto.from_dict(
            tensors=tensors,
            meta_info={"temperature": self.config.rollout.temperature},
        )

    output = output.to("cpu")

    # https://pytorch.org/docs/stable/notes/fsdp.html#fsdp-notes
    # unshard the root FSDP module
    if self.world_size > 1 and fsdp_version(self.actor.actor_module) == 1:
        self.actor.actor_module._handle.reshard(True)

    if self._is_offload_param:
        offload_fsdp_model_to_cpu(self.actor_module_fsdp)
        log_gpu_memory_usage("After offload actor model during compute_log_prob", logger=logger)

    return output

@register(dispatch_mode=make_nd_compute_dataproto_dispatch_fn(mesh_name="actor"))
@DistProfiler.annotate(color="olive", role="ref_compute_log_prob")
def compute_ref_log_prob(self, data: DataProto):
    if self._is_lora:
        # if _is_lora, actor without lora applied is the ref
        data.meta_info["is_lora"] = True
        return self.compute_log_prob(data)
    assert self._is_ref
    # else:
    # otherwise, the class have a standalone ref model

    micro_batch_size = self.config.ref.log_prob_micro_batch_size_per_gpu
    data.meta_info["micro_batch_size"] = micro_batch_size
    data.meta_info["temperature"] = self.config.rollout.temperature
    data.meta_info["max_token_len"] = self.config.ref.log_prob_max_token_len_per_gpu
    data.meta_info["use_dynamic_bsz"] = self.config.ref.log_prob_use_dynamic_bsz
    data.meta_info.setdefault("pad_token_id", self.tokenizer.pad_token_id)
    with self.ulysses_sharding_manager:
        data = data.to("cpu")  # data will to device with each micro batch on ref.compute_log_prob
        outputs = self.ref_policy.compute_log_prob(data=data, calculate_entropy=False)
        output = DataProto.from_dict(tensors={"ref_log_prob": outputs["log_probs"]})

    output = output.to("cpu")

    # https://pytorch.org/docs/stable/notes/fsdp.html#fsdp-notes
    # unshard the root FSDP module
    if self.world_size > 1:
        if fsdp_version(self.ref_policy.actor_module) == 1:
            self.ref_policy.actor_module._handle.reshard(True)
        elif fsdp_version(self.ref_policy.actor_module) == 2:
            self.ref_policy.actor_module.reshard()

    return output

@register(dispatch_mode=Dispatch.ONE_TO_ALL)
def save_checkpoint(self, local_path, hdfs_path=None, global_step=0, max_ckpt_to_keep=None):
    from verl.utils.logger import log_with_rank

    # only support save and load ckpt for actor
    assert self._is_actor

    if self._is_offload_param:
        load_fsdp_model_to_gpu(self.actor_module_fsdp)

    self.checkpoint_manager.save_checkpoint(
        local_path=local_path, hdfs_path=hdfs_path, global_step=global_step, max_ckpt_to_keep=max_ckpt_to_keep
    )
    dist.barrier()

    if self._is_lora and hasattr(getattr(self, "actor_module", self.actor_module_fsdp), "peft_config"):
        lora_save_path = os.path.join(local_path, "lora_adapter")
        peft_model = getattr(self, "actor_module", self.actor_module_fsdp)
        peft_config = {}
        if dist.get_rank() == 0:
            os.makedirs(lora_save_path, exist_ok=True)
            peft_config = asdict(peft_model.peft_config.get("default", {}))
            peft_config["task_type"] = peft_config["task_type"].value
            peft_config["peft_type"] = peft_config["peft_type"].value
            peft_config["target_modules"] = list(peft_config["target_modules"])
        try:
            if fsdp_version(self.actor_module_fsdp) > 0:
                self.actor_module_fsdp = self.actor_module_fsdp.to(get_device_name())
                lora_params = layered_summon_lora_params(self.actor_module_fsdp)
                if dist.get_rank() == 0:
                    save_file(lora_params, os.path.join(lora_save_path, "adapter_model.safetensors"))
                    with open(os.path.join(lora_save_path, "adapter_config.json"), "w", encoding="utf-8") as f:
                        json.dump(peft_config, f, ensure_ascii=False, indent=4)
        except Exception as e:
            log_with_rank(
                f"Save LoRA Adapter Error ({e})", rank=dist.get_rank(), logger=logger, log_only_rank_0=True
            )

        dist.barrier()
        log_with_rank(
            f"[rank-{self.rank}]: Saved LoRA adapter to: {lora_save_path}",

                rank=dist.get_rank(),
                logger=logger,
                log_only_rank_0=True,
            )

        if self._is_offload_param:
            offload_fsdp_model_to_cpu(self.actor_module_fsdp)

    @register(dispatch_mode=Dispatch.ONE_TO_ALL)
    def load_checkpoint(self, local_path, hdfs_path=None, del_local_after_load=False):
        assert self._is_actor or (not self._is_actor and self._is_rollout), (
            f"Checkpoint loading is only supported for Actor or standalone Rollout Workers, but got "
            f"{self._is_actor} and {self._is_rollout}"
        )

        # No checkpoint to load, just offload the model and optimizer to CPU
        if local_path is None:
            if self._is_offload_param:
                offload_fsdp_model_to_cpu(self.actor_module_fsdp)
            if self._is_offload_optimizer:
                offload_fsdp_optimizer(self.actor_optimizer)
            return

        if self._is_offload_param:
            load_fsdp_model_to_gpu(self.actor_module_fsdp)

        self.checkpoint_manager.load_checkpoint(
            local_path=local_path, hdfs_path=hdfs_path, del_local_after_load=del_local_after_load
        )

        if self._is_offload_param:
            offload_fsdp_model_to_cpu(self.actor_module_fsdp)

        if self._is_offload_optimizer:
            offload_fsdp_optimizer(self.actor_optimizer)

    @register(dispatch_mode=Dispatch.ONE_TO_ALL)
    def start_profile(self, **kwargs) -> None:
        """Start profiling for the current rank in the current training step."""
        self.profiler.start(**kwargs)

    @register(dispatch_mode=Dispatch.ONE_TO_ALL)
    def stop_profile(self) -> None:
        """Stop profiling for the current rank in the current training step."""
        self.profiler.stop()

    @register(dispatch_mode=Dispatch.ONE_TO_ALL)
    def dump_memory_snapshot(self, tag: str = "manual", sub_dir: str = None) -> None:
        """Manually trigger a CUDA memory snapshot dump on all ranks."""
        # Memory snapshot is now handled by the profiler system
        # This method is kept for backward compatibility but delegates to profiler
        if hasattr(self, "profiler") and hasattr(self.profiler, "_impl"):
            try:
                # Try to use the profiler's memory snapshot functionality
                if hasattr(self.profiler._impl, "sampler"):
                    out_dir = OmegaConf.select(self.config, "actor.profiler.save_path") or "."
                    self.profiler._impl.sampler.dump_memory_snapshot(out_dir=out_dir, tag=tag, sub_dir=sub_dir)
            except Exception:
                # silently ignore if profiler doesn't support memory snapshots
                pass


class CriticWorker(Worker, DistProfilerExtension):
    def __init__(self, config: FSDPCriticConfig):
        Worker.__init__(self)
        omega_profiler_config = config.get("profiler", {})
        profiler_config = omega_conf_to_dataclass(omega_profiler_config, dataclass_type=ProfilerConfig)
        if omega_profiler_config.get("tool", None) in ["npu", "nsys", "torch", "torch_memory"]:
            tool_config = omega_conf_to_dataclass(
                omega_profiler_config.get("tool_config", {}).get(omega_profiler_config.get("tool"))
            )
        else:
            tool_config = None
        DistProfilerExtension.__init__(
            self, DistProfiler(rank=self.rank, config=profiler_config, tool_config=tool_config)
        )
        import torch.distributed

        self.config = config
        if not torch.distributed.is_initialized():
            torch.distributed.init_process_group(
                backend=get_nccl_backend(),
                timeout=datetime.timedelta(seconds=self.config.get("nccl_timeout", 600)),
                init_method=os.environ.get("DIST_INIT_METHOD", None),
            )
        self.config: FSDPCriticConfig = config

        # build device mesh for Ulysses Sequence Parallel
        world_size = torch.distributed.get_world_size()
        from torch.distributed.device_mesh import init_device_mesh

        fsdp_size = self.config.model.fsdp_config.fsdp_size
        self.device_mesh = create_device_mesh(world_size=world_size, fsdp_size=fsdp_size)

        self.ulysses_device_mesh = None
        self.ulysses_sequence_parallel_size = self.config.get("ulysses_sequence_parallel_size", 1)
        dp = world_size // self.ulysses_sequence_parallel_size
        if self.ulysses_sequence_parallel_size > 1:
            self.ulysses_device_mesh = init_device_mesh(
                device_name, mesh_shape=(dp, self.ulysses_sequence_parallel_size), mesh_dim_names=["dp", "sp"]
            )

        # create training dispatch
        if self.ulysses_device_mesh is not None:
            is_collect = self.ulysses_device_mesh["sp"].get_local_rank() == 0
            self._register_dispatch_collect_info(
                "critic", dp_rank=self.ulysses_device_mesh["dp"].get_local_rank(), is_collect=is_collect
            )
        else:
            self._register_dispatch_collect_info("critic", dp_rank=self.rank, is_collect=True)

        self.ulysses_sharding_manager = FSDPUlyssesShardingManager(self.ulysses_device_mesh)

        # set FSDP offload params
        self._is_offload_param = self.config.model.fsdp_config.param_offload
        self._is_offload_optimizer = self.config.model.fsdp_config.optimizer_offload

        # normalize config
        self.config.ppo_mini_batch_size *= self.config.rollout_n
        self.config.ppo_mini_batch_size //= torch.distributed.get_world_size() // self.ulysses_sequence_parallel_size
        if self.config.ppo_micro_batch_size is not None:
            self.config.ppo_micro_batch_size //= (
                torch.distributed.get_world_size() // self.ulysses_sequence_parallel_size
            )
            self.config.forward_micro_batch_size //= (
                torch.distributed.get_world_size() // self.ulysses_sequence_parallel_size
            )
            self.config.ppo_micro_batch_size_per_gpu = self.config.ppo_micro_batch_size
            self.config.forward_micro_batch_size_per_gpu = self.config.forward_micro_batch_size

        if self.config.ppo_micro_batch_size_per_gpu is not None:
            assert self.config.ppo_mini_batch_size % self.config.ppo_micro_batch_size_per_gpu == 0, (
                f"normalized ppo_mini_batch_size {self.config.ppo_mini_batch_size} should be divisible by "
                f"ppo_micro_batch_size_per_gpu {self.config.ppo_micro_batch_size_per_gpu}"
            )
            assert self.config.ppo_mini_batch_size // self.config.ppo_micro_batch_size_per_gpu > 0, (
                f"normalized ppo_mini_batch_size {self.config.ppo_mini_batch_size} should be larger than "
                f"ppo_micro_batch_size_per_gpu {self.config.ppo_micro_batch_size_per_gpu}"
            )
        self._is_lora = (
            self.config.model.get("lora_adapter_path") is not None or self.config.model.get("lora_rank", 0) > 0
        )
        self.use_orig_params = self.config.model.fsdp_config.get("use_orig_params", False)

    def _build_critic_model_optimizer(self, config: FSDPCriticConfig):
        # the following line is necessary
        from torch.distributed.fsdp import MixedPrecision

        from verl.utils.model import load_valuehead_model, print_model_size
        from verl.utils.torch_dtypes import PrecisionType

        use_shm = config.model.get("use_shm", False)
        local_path = copy_to_local(config.model.path, use_shm=use_shm)
        # note that the tokenizer between actor and critic may be different. So override tokenizer info with actor info
        # using random initialized model from any architecture. May not be the same as Actor.

        tokenizer_path = copy_to_local(config.model.tokenizer_path, use_shm=use_shm)
        self.tokenizer = hf_tokenizer(tokenizer_path, trust_remote_code=config.model.get("trust_remote_code", False))
        self.processor = hf_processor(tokenizer_path, trust_remote_code=config.model.get("trust_remote_code", False))

        if self.config.model.get("custom_chat_template", None) is not None:
            if self.processor is not None:
                self.processor.chat_template = self.config.model.custom_chat_template
            else:
                self.tokenizer.chat_template = self.config.model.custom_chat_template
        override_config = OmegaConf.to_container(OmegaConf.create(self.config.model.get("override_config", {})))
        override_config_kwargs = {
            "bos_token_id": self.tokenizer.bos_token_id,
            "eos_token_id": self.tokenizer.eos_token_id,
            "pad_token_id": self.tokenizer.pad_token_id,
        }
        override_config_kwargs.update(override_config)
        if self.rank == 0:
            print(f"Critic overriding config {override_config_kwargs}")

        torch_dtype = self.config.model.fsdp_config.get("model_dtype", "fp32")
        torch_dtype = PrecisionType.to_dtype(torch_dtype)

        from transformers import AutoConfig

        # override model kwargs
        attn_implementation = override_config.get("attn_implementation", "flash_attention_2")
        critic_model_config = AutoConfig.from_pretrained(
            local_path,
            attn_implementation=attn_implementation,
            trust_remote_code=config.model.get("trust_remote_code", False),
        )
        # TODO: VL models use VisionAttention, which directly uses flash_attention in transformers>=4.53
        # which will be patched by _ulysses_flash_attention_forward, but errorly misses position_ids
        # Maybe support Ulysses in VisionAttention in the future and remove this patch
        if self.ulysses_sequence_parallel_size > 1 and hasattr(critic_model_config, "vision_config"):
            critic_model_config.vision_config._attn_implementation = "eager"

        critic_model_config.num_labels = 1
        # patch for kimi-vl
        if getattr(critic_model_config, "model_type", None) == "kimi_vl":
            critic_model_config.text_config.topk_method = "greedy"

        init_context = get_init_weight_context_manager(
            use_meta_tensor=not critic_model_config.tie_word_embeddings, mesh=self.device_mesh

                        clip_ratio_low=self.config.clip_ratio_low
                        if self.config.clip_ratio_low is not None
                        else clip_ratio,
                        clip_ratio_high=self.config.clip_ratio_high
                        if self.config.clip_ratio_high is not None
                        else clip_ratio,
                        clip_ratio_c=self.config.get("clip_ratio_c", 3.0),
                        rollout_is_weights=rollout_is_weights,
                        vocab_chunk_size=vimpo_mode["vocab_chunk_size"],
                    )
                    actor_rms_unscaled = self._global_logit_grad_rms(actor_stats_unscaled)
                    if actor_rms_unscaled is not None:
                        if vimpo_mode["vimpo_adaptive_actor_coeff"]:
                            if value_rms is None:
                                raise RuntimeError(
                                    "vimpo_adaptive_actor_coeff requires value logit-gradient RMS, but it was "
                                    "unavailable. Ensure vimpo_detach_kl=True and valid response logits exist."
                                )
                            if actor_rms_unscaled.detach().item() <= 0.0:
                                actor_coeff_for_loss = 0.0
                            else:
                                (
                                    actor_coeff_for_loss,
                                    self._vimpo_adaptive_value_logit_grad_rms_ema,
                                    self._vimpo_adaptive_actor_logit_grad_rms_unscaled_ema,
                                ) = compute_vimpo_adaptive_actor_coeff(
                                    value_logit_grad_rms=value_rms,
                                    actor_logit_grad_rms_unscaled=actor_rms_unscaled,
                                    value_logit_grad_rms_ema=self._vimpo_adaptive_value_logit_grad_rms_ema,
                                    actor_logit_grad_rms_unscaled_ema=(
                                        self._vimpo_adaptive_actor_logit_grad_rms_unscaled_ema
                                    ),
                                    alpha=vimpo_mode["vimpo_adaptive_actor_alpha"],
                                    ema_decay=vimpo_mode["vimpo_adaptive_actor_ema_decay"],
                                    eps=vimpo_mode["vimpo_adaptive_actor_eps"],
                                )
                        actor_rms = actor_rms_unscaled * float(actor_coeff_for_loss)
                        scale_metrics["actor/vimpo_actor_logit_grad_rms_unscaled"] = (
                            actor_rms_unscaled.detach().item()
                        )
                        scale_metrics["actor/vimpo_actor_logit_grad_rms"] = actor_rms.detach().item()
                    elif vimpo_mode["vimpo_adaptive_actor_coeff"]:
                        raise RuntimeError(
                            "vimpo_adaptive_actor_coeff requires actor logit-gradient RMS, but it was unavailable."
                        )
                elif vimpo_mode["vimpo_adaptive_actor_coeff"]:
                    raise NotImplementedError(
                        "vimpo_adaptive_actor_coeff requires PPO actor loss_mode='vanilla' with available "
                        "pg_loss, old_log_prob, and detached VIMPO PPO advantages."
                    )
                scale_metrics["actor/vimpo_adaptive_actor_ema_value_logit_grad_rms"] = (
                    self._vimpo_adaptive_value_logit_grad_rms_ema
                )
                scale_metrics["actor/vimpo_adaptive_actor_ema_actor_logit_grad_rms_unscaled"] = (
                    self._vimpo_adaptive_actor_logit_grad_rms_unscaled_ema
                )
                micro_batch_metrics.update(scale_metrics)

            if vimpo_mode["use_vimpo_loss"]:
                from recipe.vimpo.vimpo_core_algos import compose_vimpo_policy_loss

                policy_loss, vimpo_policy_metrics = compose_vimpo_policy_loss(
                    pg_loss=pg_loss,
                    vimpo_terminal_mse=vimpo_terminal_mse,
                    use_grpo_actor=vimpo_mode["use_grpo_actor"],
                    use_ppo_actor=vimpo_mode["use_ppo_actor"],
                    vimpo_actor_coeff=actor_coeff_for_loss,
                    device=log_prob.device,
                )
                if vimpo_mode["vimpo_adaptive_actor_coeff"] and "vimpo_actor_coeff" in vimpo_policy_metrics:
                    micro_batch_metrics["actor/vimpo_actor_coeff"] = vimpo_policy_metrics["vimpo_actor_coeff"]
            else:
                policy_loss = pg_loss if pg_loss is not None else torch.zeros([], device=log_prob.device)
            if calculate_entropy and entropy is not None:
                entropy_agg = agg_loss(loss_mat=entropy, loss_mask=response_mask, loss_agg_mode=loss_agg_mode)
                micro_batch_metrics["actor/entropy"] = entropy_agg.detach().item()
                if entropy_coeff != 0:
                    policy_loss -= entropy_agg * entropy_coeff

            if self.config.use_kl_loss:
                ref_log_prob = model_inputs["ref_log_prob"]
                # compute kl loss
                kld = kl_penalty(
                    logprob=log_prob, ref_logprob=ref_log_prob, kl_penalty=self.config.kl_loss_type
                )
                kl_loss = agg_loss(loss_mat=kld, loss_mask=response_mask, loss_agg_mode=loss_agg_mode)

                policy_loss = policy_loss + kl_loss * self.config.kl_loss_coef
                metrics["actor/kl_loss"] += kl_loss.detach().item() * loss_scale_factor
                micro_batch_metrics["actor/kl_coef"] = self.config.kl_loss_coef

            if self.config.use_dynamic_bsz:
                # relative to the dynamic bsz
                loss = policy_loss * loss_scale_factor
            else:
                loss = policy_loss * loss_scale_factor
            if self.scaler is not None:
                self.scaler.scale(loss).backward()
            else:
                loss.backward()

            if pg_loss is not None:
                metrics["actor/pg_loss"] += pg_loss.detach().item() * loss_scale_factor
            append_to_dict(metrics, micro_batch_metrics)

        grad_norm = self._optimizer_step()
        mini_batch_metrics = {"actor/grad_norm": grad_norm.detach().item()}
        append_to_dict(metrics, mini_batch_metrics)
if "actor/vimpo_value_logit_grad_rms" in metrics and "actor/vimpo_actor_logit_grad_rms" in metrics:
    value_rms_values = metrics["actor/vimpo_value_logit_grad_rms"]
    actor_rms_values = metrics["actor/vimpo_actor_logit_grad_rms"]
    if value_rms_values and actor_rms_values:
        value_rms_mean = sum(value_rms_values) / len(value_rms_values)
        actor_rms_mean = sum(actor_rms_values) / len(actor_rms_values)
        metrics["actor/vimpo_actor_to_value_logit_grad_rms_ratio"] = [
            actor_rms_mean / (value_rms_mean + 1e-12)
        ]
self._append_global_vimpo_metrics(
    metrics=metrics,
    terminal_stats=vimpo_terminal_stats,
    adv_stats=vimpo_adv_stats,
    kl_stats=vimpo_kl_stats,
    vimpo_mode=vimpo_mode,
)
self.actor_optimizer.zero_grad()
return metrics
